function presetSize(){const ratio=$('#image-ratio').value;if(ratio==='custom')return;const [w,h]=ratio.split(':').map(Number),edge=Number($('#image-resolution').value),scale=edge/Math.max(w,h);$('#image-size').value=`${Math.round(w*scale/2)*2}x${Math.round(h*scale/2)*2}`;}
