async function uploadImages(files){
 if(!conversation){toast('正在载入对话，请稍候');return;}
 if(uploading||submitting||pending){toast('请先等待当前操作完成');return;}const mode=$('#mode').value,image=mode==='image',limit=CHAT_REFERENCE_LIMIT;if(!files.length)return;if(selected.length+files.length>limit){toast(`本次最多${limit}份参考素材`);return;}
 const allowed=['image/png','image/jpeg','image/webp',...(image?[]:['video/mp4','video/webm','video/quicktime',...(mode==='chat'?['audio/wav','audio/mpeg','audio/mp3','audio/aac','audio/aiff','audio/flac','audio/ogg','audio/webm','audio/mp4','audio/m4a']:[])])];
 const fileKind=f=>documentKind(f.name)?'document':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'image';
 if(files.some(f=>!(allowed.includes(f.type)||!image&&documentKind(f.name))||f.size>(fileKind(f)==='document'?DOCUMENT_LIMIT:fileKind(f)==='video'?(mode==='chat'&&$('#video-input-mode').value==='native'?CHAT_NATIVE_VIDEO_MAX_BYTES:150*1024*1024):fileKind(f)==='audio'?10*1024*1024:10*1024*1024)||!f.size)){toast(image?'请选择不超过10MB的 PNG/JPEG/WebP 图片':'图片≤10MB；视频抽样模式≤150MB、原视频模式≤10MB；音频≤10MB；文字、DOCX/XLSX 文档≤20MB。原视频和音频理解目前仅支持已启用的 Gemini 原生对话');return;}
 if(selected.filter(isVideo).length+files.filter(f=>f.type.startsWith('video/')).length>3){toast('每次最多3份视频');return;}if(selected.filter(isAudio).length+files.filter(f=>f.type.startsWith('audio/')).length>1){toast('每条消息最多附加1份音频');return;}
 uploading=true;showJob();try{const ids=[...selected];for(const file of files){const response=await fetch((!image&&documentKind(file.name)?'/api/chat-documents/import':'/api/assets')+'?name='+encodeURIComponent(file.name||'粘贴图片.png'),{method:'POST',headers:{'content-type':file.type},body:file});const a=await response.json();if(!response.ok)throw Error(a.error||'本地素材保存失败');mediaAssets.set(a.id,a);ids.push(a.id);}await prepareSelection(ids);toast('素材已保存到本机并加入本次参考；视频、音频和文档可预览');}catch(e){toast(e.message);}finally{uploading=false;$('#upload-files').value='';showJob();}
}
