$('#pick').onclick=async()=>{if(uploading||submitting||pending)return;try{project=await api('/api/projects/'+projectId);for(const a of project.assets)mediaAssets.set(a.id,a);const image=$('#mode').value==='image',assets=[...new Map([...project.assets,...selected.map(id=>mediaAssets.get(id)).filter(Boolean)].map(a=>[a.id,a])).values()].filter(a=>['image/png','image/jpeg','image/webp',...(image?[]:['video/mp4','video/webm','video/quicktime'])].includes(a.type)||!image&&(a.type.startsWith('audio/')||isDocument(a)));modal(image?'选择项目图片':'选择项目图片、视频、音频或文档',assets.length?`<div class="pictures">${assets.map(a=>`<label class="picture">${isDocument(a)?'<span class="document-icon">文档</span>':a.type.startsWith('video/')?`<video src="/media/${a.id}" preload="metadata" muted></video><small>视频</small>`:a.type.startsWith('audio/')?`<audio src="/media/${a.id}" preload="metadata" controls></audio><small>音频</small>`:`<img src="/media/${a.id}" alt="">`}<span>${esc(a.name)}</span><input type="checkbox" name="image" value="${a.id}" ${selected.includes(a.id)?'checked':''}></label>`).join('')}</div>`:'<p>请先在画布导入素材并加入当前项目，或使用上传素材。</p>','<button id="close">取消</button><button id="choose">使用所选素材</button>');$('#close').onclick=close;$('#choose').onclick=async()=>{const chosen=[...document.querySelectorAll('[name=image]:checked')].map(e=>e.value);if(chosen.length>CHAT_REFERENCE_LIMIT||chosen.filter(isVideo).length>3||chosen.filter(isAudio).length>1){toast('最多20份素材，其中视频最多3份、音频最多1份');return;}uploading=true;$('#choose').disabled=true;showJob();try{await prepareSelection(chosen);close();}catch(e){toast(e.message);$('#choose').disabled=false;}finally{uploading=false;showJob();}};}catch(e){toast(e.message);}};
