$('#messages').onclick=async e=>{if(e.target.dataset.document){previewDocument(e.target.dataset.document);return;}if(e.target.dataset.nativePreview){previewNativeVideo(e.target.dataset.nativePreview);return;}if(e.target.dataset.preview){previewSample(e.target.dataset.preview);return;}const assetId=e.target.dataset.reference||e.target.dataset.discuss;if(assetId){if(submitting||pending||uploading||job&&['queued','running'].includes(job.status)){toast('请先等待当前请求完成');return;}const mode=e.target.dataset.reference?'image':'chat',limit=CHAT_REFERENCE_LIMIT;if(mode==='image'&&selected.some(id=>isVideo(id)||isDoc(id))){toast('请先移除视频或文档，再继续改图');return;}if(!selected.includes(assetId)&&selected.length>=limit){toast('请先移除部分参考图');return;}$('#mode').value=mode;drawPlatforms();if(!selected.includes(assetId)){if(selectedDocuments.size){uploading=true;showJob();try{await prepareSelection([...selected,assetId]);}catch(error){toast(error.message);return;}finally{uploading=false;showJob();}}else{selected.push(assetId);attachments();}}$('#text').focus();toast(mode==='image'?'已加入参考，请填写修改要求':'已加入参考，请选择支持图片的对话模型');return;}if(!e.target.dataset.apply)return;const m=conversation.messages.find(m=>m.id===e.target.dataset.apply);if(m.state==='incomplete'){modal('使用未完成片段','<p>这次任务没有完整完成。确认后将已保存的文字或图片放入画布，不会向模型重新发送。</p>','<button id="close">取消</button><button id="apply-partial" class="primary">确认使用片段</button>');$('#close').onclick=close;$('#apply-partial').onclick=()=>{ $('#apply-partial').disabled=true;applyMessage(m.id,true);};}else{e.target.disabled=true;await applyMessage(m.id);}};
