try{project=await api('/api/projects/'+projectId);for(const a of project.assets)mediaAssets.set(a.id,a);$('#project-name').textContent=project.name;$('#back').href='/?project='+projectId;$('#creation').href='/creation-studio?projectId='+projectId;platforms=(await api('/api/platforms')).platforms;capabilities=(await api('/api/health')).capabilities||{};$('#executor option[value=codex]').disabled=capabilities.codexConversations!==true;$('#executor option[value=gemini-cli]').disabled=capabilities.geminiCliConversations!==true;drawPlatforms();items=await api('/api/conversations?projectId='+projectId);const requested=new URLSearchParams(location.search).get('conversation');await open(requested||items[0]?.id||(await api('/api/conversations','POST',{projectId})).id);}catch(e){toast(e.message);$('#messages').textContent=e.message;}finally{document.querySelector('main').inert=false;}
